import java.util.Scanner;

public class P1047D {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        long n = scan.nextInt();
        long m = scan.nextInt();
        long min = Math.min(n, m);
        long max = Math.max(n, m);
        long ans;

        switch ((int) min) {
            case 1:
                ans = max / 6 * 6 + 2 * Math.max(0, max % 6 - 3);
                break;
            case 2:
                switch ((int) max) {
                    case 2:
                        ans = 0;
                        break;
                    case 3:
                        ans = 4;
                        break;
                    case 7:
                        ans = 12;
                        break;
                    default:
                        ans = usual(min, max);
                        break;
                }
                break;
            case 3:
                ans = (max == 3) ? 8 : usual(min, max);
                break;
            default:
                ans = usual(min, max);
                break;
        }

        System.out.println(ans);
    }

    private static long usual(long min, long max) {
        if (max % 2 == 0) {
            return min * max;
        }
        return min * max - min * max % 2;
    }
}
